  "Must be at least {n} characters.": ["{n} 文字以上にしてください。","至少需要 {n} 个字符。","至少需要 {n} 個字元。","Debe tener al menos {n} caracteres.","Doit comporter au moins {n} caractères.","Muss mindestens {n} Zeichen lang sein.","Deve avere almeno {n} caratteri."],
  "Must be at most {n} characters.": ["{n} 文字以下にしてください。","最多 {n} 个字符。","最多 {n} 個字元。","Debe tener como máximo {n} caracteres.","Doit comporter au plus {n} caractères.","Darf höchstens {n} Zeichen lang sein.","Deve avere al massimo {n} caratteri."],
  "Must be one of: {list}": ["次のいずれかにしてください: {list}","必须是以下之一：{list}","必須是以下之一：{list}","Debe ser uno de: {list}","Doit être l’un de : {list}","Muss eines von diesen sein: {list}","Deve essere uno tra: {list}"],
  "Must be {max} or less.": ["{max} 以下にしてください。","必须小于或等于 {max}。","必須小於或等於 {max}。","Debe ser {max} o menos.","Doit être inférieur ou égal à {max}.","Muss {max} oder weniger sein.","Deve essere {max} o meno."],
  "Must be {min} or more.": ["{min} 以上にしてください。","必须大于或等于 {min}。","必須大於或等於 {min}。","Debe ser {min} o más.","Doit être supérieur ou égal à {min}.","Muss {min} oder mehr sein.","Deve essere {min} o più."],
